gq 3;
query hybrid($q: String, $v: Vector(3)) {
  match {
    from {
      match {
        from distance({ match { $d: Doc } return { $d } }, $d.embedding, $v)
      }
      return { $d, $distance as dist }
    }
    from {
      match {
        from bm25({ match { $e: Doc } return { $e } }, $e.body, $q)
      }
      return { $e as d2, $score as bm }
    }
    $d = $d2
    let $s = 0.7 * (1.0 / (1.0 + $dist)) + 0.3 * $bm
  }
  return { $d.title, $s as s }
  order { s desc }
  limit 10
}
